class SingleSourceQuerySerializationTest {

	@ParameterizedTest
	@MethodSource("resultBindings")
	void bindingNamesAndAnalysisSurviveSerialization(QueryType type, Set<String> names, Set<String> assured)
			throws Exception {
		QueryInfo queryInfo = mock(QueryInfo.class);
		when(queryInfo.getQueryType()).thenReturn(type);
		var query = new SingleSourceQuery(new StatementPattern(Var.of("s"), Var.of("p"), Var.of("o")),
				mock(Endpoint.class), queryInfo);
		var originalFacts = QueryAlgebraBindingAnalysis.withGuaranteedInputNames(query, Set.of()).outputFacts(query);

		var bytes = new ByteArrayOutputStream();
		try (var output = new ObjectOutputStream(bytes)) {
			output.writeObject(query);
		}
		try (var input = new ObjectInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {
			var restored = (SingleSourceQuery) input.readObject();
			assertThat(restored.getQueryInfo()).isNull();
			assertThat(restored.getBindingNames()).isEqualTo(names);
			assertThat(restored.getAssuredBindingNames()).isEqualTo(assured);
			var restoredFacts = QueryAlgebraBindingAnalysis.withGuaranteedInputNames(restored, Set.of())
					.outputFacts(restored);
			assertThat(restoredFacts.possibleOutputsKnown()).isEqualTo(originalFacts.possibleOutputsKnown());
			assertThat(restoredFacts.possibleOutputs()).isEqualTo(originalFacts.possibleOutputs());
			assertThat(restoredFacts.guaranteedOutputs()).isEqualTo(originalFacts.guaranteedOutputs());
		}
	}

	private static Stream<Arguments> resultBindings() {
		Set<String> childNames = Set.of("s", "p", "o");
		Set<String> graphNames = Set.of("subject", "predicate", "object", "context");
		Set<String> assuredGraphNames = Set.of("subject", "predicate", "object");
		return Stream.of(
				Arguments.of(QueryType.SELECT, childNames, childNames),
				Arguments.of(QueryType.ASK, Set.of(), Set.of()),
				Arguments.of(QueryType.CONSTRUCT, graphNames, assuredGraphNames),
				Arguments.of(QueryType.DESCRIBE, graphNames, assuredGraphNames),
				Arguments.of(null, childNames, childNames));
	}
}
